def parse_query_params(url: str) -> dict[str, list[str]]:
    """
    Parses query parameters from a URL string, handling URL decoding,
    '+' as space, and preserving order for repeated keys.
    """
    if '?' not in url:
        return {}

    # Extract query string: after '?' and before '#'
    query_part = url.split('?', 1)[1].split('#', 1)[0]

